      "code": "G06K7/10267",
      "level": 11,
      "parent": "G06K7/10257",
      "ja": "｛質問器の内部回路を構成する機構｝",
      "en": "{the arrangement comprising a circuit inside of the interrogation device}",
      "count": 54,
      "ipcCode": "G06K7/10",
      "coreCode": "G06K7/10",
      "note": "",
      "sourceFile": "cpc_G06K.txt",
