      "ja": "｛温度センサや加速度センサのような，環境パラメータを感知するための機構を含む質問器，例．オン／オフのトリガー手段または警告手段として使用される機構を含むもの｝",
      "en": "{the interrogation device including an arrangement for sensing environmental parameters, such as a temperature or acceleration sensor, e.g. used as an on/off trigger or as a warning means}",
      "count": 112,
      "ipcCode": "G06K7/10",
      "coreCode": "G06K7/10",
