      "level": 14,
      "parent": "G06K7/10435",
      "ja": "｛エンドレステープに取り付けられる記録担体，すなわち，少なくとも別の物体に取り付けられない記録担体｝",
      "en": "{the record carriers being fixed to an endless tape or at least not fixed to further objects}",
      "count": 34,
