    "G06K11/00": {
      "code": "G06K11/00",
      "level": 7,
      "parent": null,
      "ja": "グラフ読取りのためのまたは機械的変量，例．力または存否，のパターンを電気信号に変換するための方法または装置（文字またはパターン認識と結合しているものＧ０６Ｋ９／００；機械工具上に取り付けた複製装置のための探触子Ｂ２３Ｑ３５／００；面積測定のための装置Ｇ０１Ｂ；力の測定Ｇ０１Ｌ；計算機の入力装置として適合させられたものＧ０６Ｆ３／００；一定基準系に対する対象物の位置の伝送方式，例．テレライタ，Ｇ０８Ｃ２１／００）",
      "en": "Methods or arrangements for graph-reading or for converting the pattern of mechanical parameters, e.g. force or presence, into electrical signal (feelers for copying devices on machine tools B23Q35/00; arrangements for measuring areas G01B; measuring force G01L; adapted as input devices to computers G06F3/00; combined with pattern recognition G06F18/00; arrangements for image or video recognition or understanding G06V10/00; character recognition, recognising digital ink or document-oriented image-based pattern recognition G06V30/00; systems for transmitting the position of an object with respect to a predetermined reference system, e.g. tele-autographic system, G08C21/00)<br><br><u>WARNING</u><br> This group and its subgroups are no longer used for the classification of new documents as from 1 January 2006. Documents relating to methods and arrangements for input to a computer are classified under G06F3/033 and G06F3/041",
      "count": 260,
      "ipcCode": "G06K11/00",
      "coreCode": "G06K11/00",
      "note": "",
      "sourceFile": "cpc_G06K.txt",
      "kind": "cpc"
    },
