      "code": "G06K15/00",
      "level": 7,
      "parent": null,
      "ja": "出力データの永久可視表示を作成するための装置｛（印刷ヘッドの構造Ｂ４１Ｊ２／００；伝送に関係する映像の走査および再生の装置，例．ファクシミリＨ０４Ｎ１／００；写植のためのものＢ４１Ｂ１９／００）｝｛注．このグループにおいては，＋ＩＤＴという表現は以下の内容を意味する。　－ここに分類されている文献は，記録データの処理に関連するＩＤＴ‐グループに分類されていた:　－それらは管理上，前のＩＤＴグループから，このグループへ再分類された。｝",
      "en": "Arrangements for producing a permanent visual presentation of the output data {, e.g. computer output printers}(printing or plotting combined with another operation, e.g. with conveying, G06K17/00)",
