      "level": 9,
      "parent": "G06K17/0022",
      "ja": "｛無線記録担体でタグ付けされた物品であって，グループ分けされるかまとめられた物品への無線による質問に特に適用される装置｝",
      "en": "{the arrangement being specially adapted for wireless interrogation of grouped or bundled articles tagged with wireless record carriers}",
      "count": 8076,
