      "ja": "｛保持装置への挿入を容易にするための構成をなす記録担体，例．箱またはケースに記録担体を適合させる装置（チケットホルダーＡ４５Ｃ１１／１８）｝",
      "en": "{the record carrier comprising an arrangement to facilitate insertion into a holding device, e.g. an arrangement that makes the record carrier fit into an etui or a casing (ticket holders A45C11/18)}",
