      "ja": "｛折り畳むために柔軟なまたは適応的な材料，例．ＲＦＩＤを担持する，荷物ラベル，ＩＤタグ，フォームまたは身分証明書，に使用される紙または紙のような材料（有価証券，例．紙幣またはパスポート，の真贋を判定する方法Ｇ０７Ｄ７／００；冊子体のようなものの構造上の特徴Ｂ４２Ｄ）｝",
      "en": "{the material being flexible or adapted for folding, e.g. paper or paper-like materials used in luggage labels, identification tags, forms or identification documents carrying RFIDs (methods for testing the genuineness of valuable papers, e.g. banknotes or passports G07D7/00; constructional features of booklets and the like B42D)}",
