    "G06K19/07739": {
      "code": "G06K19/07739",
      "level": 13,
      "parent": "G06K19/07737",
      "ja": "｛単独で記録担体として機能し得る第１の部品と，一部を変えた形状として単に機能する第２の部品を含むもの，例．標準的なスマートカードの形状に取り外し可能に取り付けられる，タイプＩＤが０００１のＳＩＭカード｝",
      "en": "{comprising a first part capable of functioning as a record carrier on its own and a second part being only functional as a form factor changing part, e.g. SIM cards type ID 0001, removably attached to a regular smart card form factor}",
      "count": 471,
      "ipcCode": "G06K19/077",
      "coreCode": "G06K19/077",
      "note": "",
      "sourceFile": "cpc_G06K.txt",
      "kind": "cpc"
    },
    "G06K19/07741": {
      "code": "G06K19/07741",
      "level": 13,
      "parent": "G06K19/07737",
      "ja": "｛標準的な記録担体として動作する第１の部品と，当該記録担体の機能的な態様を変更する付加的な第２の部品を含むもの，例．接触型カードに取り付けられたとき，当該接触型カードを非接触型カードとして機能させるアダプター部品を備えた接触型ベースのスマートカード｝",
      "en": "{comprising a first part operating as a regular record carrier and a second attachable part that changes the functional appearance of said record carrier, e.g. a contact-based smart card with an adapter part which, when attached to the contact card makes the contact card function as a non-contact card}",
      "count": 464,
      "ipcCode": "G06K19/077",
      "coreCode": "G06K19/077",
      "note": "",
      "sourceFile": "cpc_G06K.txt",
      "kind": "cpc"
    },
