      "ja": "｛同様の複数の記録担体を重ねることを可能にする記録担体の装置，例．複数の記録担体が行う非接触通信の間の干渉を回避するもの｝",
      "en": "{arrangements on the record carrier to allow stacking of a plurality of similar record carriers, e.g. to avoid interference between the non-contact communication of the plurality of record carriers}",
